import{_t as e,at as t,et as n,it as r,n as i,rt as a}from"./chunks/framework.B5d4da8a.js";var o=JSON.parse(`{"title":"Semantic atoms: how new meaning enters the object language","description":"","frontmatter":{"title":"Semantic atoms: how new *meaning* enters the object language","type":"adr","date":"2026-10-14T00:00:00.000Z","status":"proposed"},"headers":[],"relativePath":"graphopt/project/adrs/0007-semantic-atom-minting.md","filePath":"vendored/graphopt/project/adrs/0007-semantic-atom-minting.md"}`),s={name:`graphopt/project/adrs/0007-semantic-atom-minting.md`};function c(i,o,s,c,l,u){return e(),a(`div`,null,[...o[0]||=[r(`<h1 id="adr-0007-—-semantic-atoms-how-new-meaning-enters-the-object-language" tabindex="-1">ADR 0007 — Semantic atoms: how new <em>meaning</em> enters the object language <a class="header-anchor" href="#adr-0007-—-semantic-atoms-how-new-meaning-enters-the-object-language" aria-label="Permalink to “ADR 0007 — Semantic atoms: how new meaning enters the object language”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><strong>Minting a semantic atom becomes a pipeline, not an event</strong> — four layers, each with its own evidence requirement, all admitted through the ADR-0004 gauntlet (oracle → typed gate → certificate replay → adversarial sweep → measured pay).</p><h3 id="layer-1-—-definitional-atoms-compression-sound-by-construction" tabindex="-1">Layer 1 — definitional atoms (compression; sound by construction) <a class="header-anchor" href="#layer-1-—-definitional-atoms-compression-sound-by-construction" aria-label="Permalink to “Layer 1 — definitional atoms (compression; sound by construction)”">​</a></h3><p>Anti-unify recurring subgraphs in saturated e-graphs; mint a named atom whose semantics IS its expansion (macro / definitional extension, Babble-style library learning). No new meaning is claimed — the atom unfolds to a known term — so soundness is free. The value is <em>compression of the reachable set</em>: named structure makes deeper compositions fit the iteration budget. This is the engine ADR 0004 assumed.</p><h3 id="layer-2-—-handler-interpreted-atoms-semantics-by-denotation" tabindex="-1">Layer 2 — handler-interpreted atoms (semantics by denotation) <a class="header-anchor" href="#layer-2-—-handler-interpreted-atoms-semantics-by-denotation" aria-label="Permalink to “Layer 2 — handler-interpreted atoms (semantics by denotation)”">​</a></h3><p>An atom minted with a proposed <em>handler body</em> — code drawn from a structured grammar of tensor primitives (loop-shaped, fold-shaped, two-axis-contraction templates — NOT free-form Python; free-form is where the search explodes). <code>genkernel</code> is the elementwise special case; this generalizes the proposal site to non-elementwise skeletons. Evidence: the handler is verified numerically against the pre-mint subterm it compresses, on the full measured domain — same bar as a law.</p><h3 id="layer-3-—-law-theoretic-atoms-equational-grounding" tabindex="-1">Layer 3 — law-theoretic atoms (equational grounding) <a class="header-anchor" href="#layer-3-—-law-theoretic-atoms-equational-grounding" aria-label="Permalink to “Layer 3 — law-theoretic atoms (equational grounding)”">​</a></h3><p>The algebraic level: mint an atom with <strong>no body</strong>, only the laws it is hypothesized to satisfy. This is how primitives legitimately enter mathematics — &quot;scan&quot; is defined by the fold law, not by an implementation. Consistency is checkable: does the induced equational theory stay coherent under saturation, and does any paying extraction result? The closing loop already exists in pieces: <strong>handler → measured bindings → <code>dspec_synth</code>/<code>auto_cond</code> synthesize the laws the atom satisfies → <code>verify_law</code> certifies them.</strong> A runtime <em>self-assembles</em> when that loop runs over a coherent atom set.</p><h3 id="layer-4-—-induced-atoms-approximate-semantics" tabindex="-1">Layer 4 — induced atoms (approximate semantics) <a class="header-anchor" href="#layer-4-—-induced-atoms-approximate-semantics" aria-label="Permalink to “Layer 4 — induced atoms (approximate semantics)”">​</a></h3><p>A handler <em>learned</em> to match observed computation — the only layer that breaks exactness, so it is <strong>confined to the certified-error lane</strong>: admitted only as a bounded member with a carried <code>error_budget</code>, never as a semantic equivalence. ADR 0003 is the guardrail: a fit handler is an <em>execution</em> candidate, never a <em>semantics</em> claim.</p><h3 id="the-emergent-runtime-thesis" tabindex="-1">The emergent-runtime thesis <a class="header-anchor" href="#the-emergent-runtime-thesis" aria-label="Permalink to “The emergent-runtime thesis”">​</a></h3><p>When layers 2+3 run to fixpoint over a domain, the output IS a runtime: {minted atoms, their handlers, their certified laws} — the shape <code>catopt-carriers</code> already has, assembled by measurement instead of by hand. <code>vocab</code>&#39;s refusal-driven need-detection supplies the proposal frontier (it already knows which atoms are wanted); <code>enumerate</code>/<code>forms</code> supply the law candidates around them.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The e-graph composes and folds exactly what its vocabulary can spell. Measured so far: the RetNet fold is a <em>rediscovery</em> — the carrier the machine extracted is numerically identical (9.8e-9 fp64) to the paper&#39;s published chunkwise duality (<code>lab/probes/retnet_baseline_probe.py</code>), and hand-tuned baselines still beat the delivered artifact. The discovery machinery can mint new <em>spellings</em> (law instances, guards, derives, paying forms — <code>square(X)=square(neg X)</code> was non-derivable), and new <em>operators-as-implementations</em> (<code>genkernel</code> binds a measured elementwise pattern to a generated kernel). What it cannot yet do is mint a new <strong>semantic atom</strong> — an op whose <em>meaning</em> did not exist in the library before.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2>`,18),n(`ul`,null,[n(`li`,null,[n(`strong`,null,`The library stops being the bottleneck.`),t(` Carrier atoms today are`)]),n(`li`,null,[n(`strong`,null,`Discovery changes claim.`),t(` From "rediscovered a published`)]),n(`li`,null,[n(`strong`,null,`Everything still passes the same gauntlet.`),t(` A minted atom is a`)]),n(`li`,{"atoms,":``,"handlers,":``,laws:``},[n(`strong`,null,`Runtimes become artifacts.`),t(` A coherent`)])],-1),r(`<h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0007-semantic-atom-minting.html"><code>design/0007-semantic-atom-minting.md</code></a>.</p>`,4)]])}var l=i(s,[[`render`,c]]);export{o as __pageData,l as default};